def run(context):
    holdings = context['portfolio_state']
    recommendations = {'add_candidates': [], 'trim_candidates': []}
    for holding in holdings:
        if holding['trading_signal'] in ['STRONG_BUY', 'BUY']:
            recommendations['add_candidates'].append(holding)
        elif holding['trading_signal'] == 'SELL':
            recommendations['trim_candidates'].append(holding)
    return recommendations
